-- Evolve the existing projection: stable identifiers retain their original value.
CREATE TABLE cmdb_schema_version(id text PRIMARY KEY,document jsonb NOT NULL,content_hash text NOT NULL UNIQUE,status text NOT NULL CHECK(status IN('active','retired')),created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX cmdb_one_active_schema ON cmdb_schema_version(status) WHERE status='active';
CREATE TABLE cmdb_schema_attribute(schema_version text NOT NULL REFERENCES cmdb_schema_version(id),asset_type text NOT NULL,field_name text NOT NULL,definition jsonb NOT NULL,PRIMARY KEY(schema_version,asset_type,field_name));
CREATE TABLE cmdb_relationship_definition(schema_version text NOT NULL REFERENCES cmdb_schema_version(id),name text NOT NULL,definition jsonb NOT NULL,PRIMARY KEY(schema_version,name));
ALTER TABLE cmdb_entity ADD COLUMN bom_item_uid uuid UNIQUE REFERENCES bom_item(item_uid);
UPDATE cmdb_entity SET bom_item_uid=item_uid;
ALTER TABLE cmdb_entity DROP CONSTRAINT cmdb_entity_item_uid_fkey;
ALTER TABLE cmdb_entity ALTER COLUMN item_uid TYPE text USING item_uid::text;
ALTER TABLE cmdb_entity ADD COLUMN asset_type text NOT NULL DEFAULT 'device';
ALTER TABLE cmdb_entity ADD COLUMN name text NOT NULL DEFAULT '';
ALTER TABLE cmdb_entity ADD COLUMN serial text;
ALTER TABLE cmdb_entity ADD COLUMN lifecycle_state text NOT NULL DEFAULT 'planned';
ALTER TABLE cmdb_entity ADD COLUMN health text NOT NULL DEFAULT 'unknown';
ALTER TABLE cmdb_entity ADD COLUMN maintenance_state text NOT NULL DEFAULT 'unknown';
ALTER TABLE cmdb_entity ADD COLUMN freshness text NOT NULL DEFAULT 'unknown';
ALTER TABLE cmdb_entity ADD COLUMN version bigint NOT NULL DEFAULT 1;
ALTER TABLE cmdb_entity ADD COLUMN schema_version text;
ALTER TABLE cmdb_entity ADD COLUMN source_type text NOT NULL DEFAULT 'bom';
ALTER TABLE cmdb_entity ADD COLUMN source_ref text NOT NULL DEFAULT '';
ALTER TABLE cmdb_entity ADD COLUMN source_updated_at timestamptz;
ALTER TABLE cmdb_entity ADD COLUMN created_at timestamptz NOT NULL DEFAULT now();
UPDATE cmdb_entity SET asset_type=CASE payload->>'category' WHEN 'optic_module' THEN 'optic' ELSE COALESCE(payload->>'category','device') END,name=COALESCE(NULLIF(payload->>'hostname',''),payload->>'item_uid',item_uid),serial=NULLIF(payload->>'serial','');
CREATE INDEX cmdb_entity_catalog ON cmdb_entity(asset_type,name,item_uid);
CREATE INDEX cmdb_entity_serial ON cmdb_entity(serial) WHERE serial IS NOT NULL;
CREATE TABLE cmdb_asset_scope(project_id text NOT NULL REFERENCES project(id),asset_id text NOT NULL REFERENCES cmdb_entity(item_uid),source_ref text NOT NULL,PRIMARY KEY(project_id,asset_id));
INSERT INTO cmdb_asset_scope SELECT DISTINCT p.project_id,p.item_uid::text,'bom:'||p.revision_id::text FROM project_asset p JOIN cmdb_entity e ON e.item_uid=p.item_uid::text ON CONFLICT DO NOTHING;
CREATE INDEX cmdb_asset_scope_asset ON cmdb_asset_scope(asset_id,project_id);
CREATE TABLE cmdb_revision(id uuid PRIMARY KEY,asset_id text NOT NULL REFERENCES cmdb_entity(item_uid),version bigint NOT NULL,schema_version text NOT NULL,payload jsonb NOT NULL,before_payload jsonb,status text NOT NULL DEFAULT 'Published',source_type text NOT NULL,source_ref text NOT NULL,operator text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(asset_id,version));
CREATE TABLE cmdb_field_source(id uuid PRIMARY KEY,asset_id text NOT NULL REFERENCES cmdb_entity(item_uid),field_name text NOT NULL,value jsonb NOT NULL,source_type text NOT NULL,source_ref text NOT NULL,source_location jsonb NOT NULL DEFAULT '{}',fact_layer text NOT NULL,observed_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),revision text NOT NULL,operator text NOT NULL,confidence double precision,approval_status text NOT NULL,support text NOT NULL DEFAULT 'unknown',freshness text NOT NULL DEFAULT 'unknown',evidence_refs jsonb NOT NULL DEFAULT '[]',UNIQUE(asset_id,field_name,source_ref,fact_layer));
CREATE INDEX cmdb_field_source_asset ON cmdb_field_source(asset_id,field_name,updated_at DESC);
ALTER TABLE cmdb_relationship DROP CONSTRAINT cmdb_relationship_from_uid_fkey;
ALTER TABLE cmdb_relationship DROP CONSTRAINT cmdb_relationship_to_uid_fkey;
ALTER TABLE cmdb_relationship DROP CONSTRAINT cmdb_relationship_pkey;
ALTER TABLE cmdb_relationship ALTER COLUMN from_uid TYPE text USING from_uid::text;
ALTER TABLE cmdb_relationship ALTER COLUMN to_uid TYPE text USING to_uid::text;
ALTER TABLE cmdb_relationship ALTER COLUMN revision_id DROP NOT NULL;
ALTER TABLE cmdb_relationship ADD COLUMN id uuid NOT NULL DEFAULT gen_random_uuid();
ALTER TABLE cmdb_relationship ADD PRIMARY KEY(id);
ALTER TABLE cmdb_relationship ADD FOREIGN KEY(from_uid) REFERENCES cmdb_entity(item_uid);
ALTER TABLE cmdb_relationship ADD FOREIGN KEY(to_uid) REFERENCES cmdb_entity(item_uid);
ALTER TABLE cmdb_relationship ADD COLUMN definition_id text NOT NULL DEFAULT 'reference';
ALTER TABLE cmdb_relationship ADD COLUMN project_id text NOT NULL DEFAULT '';
ALTER TABLE cmdb_relationship ADD COLUMN fact_layer text NOT NULL DEFAULT 'planned';
ALTER TABLE cmdb_relationship ADD COLUMN source_type text NOT NULL DEFAULT 'bom';
ALTER TABLE cmdb_relationship ADD COLUMN source_ref text NOT NULL DEFAULT '';
ALTER TABLE cmdb_relationship ADD COLUMN relationship_status text NOT NULL DEFAULT 'active';
ALTER TABLE cmdb_relationship ADD COLUMN direction text NOT NULL DEFAULT 'outbound';
ALTER TABLE cmdb_relationship ADD COLUMN cardinality text NOT NULL DEFAULT 'many-to-many';
ALTER TABLE cmdb_relationship ADD COLUMN version bigint NOT NULL DEFAULT 1;
ALTER TABLE cmdb_relationship ADD COLUMN valid_from timestamptz NOT NULL DEFAULT now();
ALTER TABLE cmdb_relationship ADD COLUMN valid_to timestamptz;
ALTER TABLE cmdb_relationship ADD COLUMN created_at timestamptz NOT NULL DEFAULT now();
UPDATE cmdb_relationship e SET project_id=r.project_id,source_ref=r.id::text,valid_from=r.created_at FROM bom_revision r WHERE e.revision_id=r.id;
WITH ranked AS(SELECT id,row_number() OVER(PARTITION BY from_uid,to_uid,kind ORDER BY valid_from DESC,id) AS n FROM cmdb_relationship) UPDATE cmdb_relationship e SET valid_to=e.valid_from,relationship_status='historical' FROM ranked r WHERE e.id=r.id AND r.n>1;
CREATE UNIQUE INDEX cmdb_relationship_active ON cmdb_relationship(from_uid,to_uid,kind,fact_layer) WHERE valid_to IS NULL;
CREATE UNIQUE INDEX cmdb_relationship_legacy ON cmdb_relationship(from_uid,to_uid,kind,revision_id);
CREATE INDEX cmdb_relationship_source ON cmdb_relationship(from_uid,project_id) WHERE valid_to IS NULL;
CREATE INDEX cmdb_relationship_target ON cmdb_relationship(to_uid,project_id) WHERE valid_to IS NULL;
CREATE TABLE cmdb_relationship_revision(id uuid PRIMARY KEY,relationship_id uuid NOT NULL,version bigint NOT NULL,payload jsonb NOT NULL,source_ref text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(relationship_id,version));
CREATE TABLE cmdb_lifecycle_event(id text PRIMARY KEY,project_id text NOT NULL REFERENCES project(id),asset_id text NOT NULL REFERENCES cmdb_entity(item_uid),event_type text NOT NULL,label text NOT NULL,status text NOT NULL,stage_id text,source_type text NOT NULL,source_ref text NOT NULL,operator text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),links jsonb NOT NULL DEFAULT '[]',details jsonb NOT NULL DEFAULT '{}');
CREATE INDEX cmdb_lifecycle_asset ON cmdb_lifecycle_event(asset_id,occurred_at DESC);
CREATE TABLE cmdb_changeset(id uuid PRIMARY KEY,project_id text NOT NULL REFERENCES project(id),title text NOT NULL,reason text NOT NULL,status text NOT NULL CHECK(status IN('Draft','Review','Approved','Published','Rejected')),version bigint NOT NULL DEFAULT 1,schema_version text NOT NULL,changes jsonb NOT NULL,requester_id uuid NOT NULL REFERENCES app_user(id),reviewer_id uuid REFERENCES app_user(id),review_reason text,branch_ref text,base_ref text,idempotency_key text NOT NULL,request_hash text NOT NULL,error_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz,UNIQUE(project_id,idempotency_key));
CREATE TABLE cmdb_ingest_event(event_id text PRIMARY KEY,source_type text NOT NULL,source_ref text NOT NULL,processed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cmdb_saved_view(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_user(id),name text NOT NULL,query text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,name));
-- Dedicated evidence index: raw domain snapshots/logs/time series remain in object storage.
CREATE TABLE cmdb_external_reference(resource text NOT NULL,record_id text NOT NULL,project_id text NOT NULL REFERENCES project(id),asset_ids text[] NOT NULL DEFAULT '{}',object_key text NOT NULL,content_hash text NOT NULL,summary jsonb NOT NULL DEFAULT '{}',source_type text NOT NULL DEFAULT 'synthetic',PRIMARY KEY(resource,record_id,project_id));
CREATE INDEX cmdb_external_assets ON cmdb_external_reference USING gin(asset_ids);
CREATE INDEX cmdb_external_scope ON cmdb_external_reference(project_id,resource);
CREATE TABLE cmdb_config_reference(id text NOT NULL,project_id text NOT NULL REFERENCES project(id),asset_id text NOT NULL REFERENCES cmdb_entity(item_uid),layer text NOT NULL CHECK(layer IN('baseline','intended','actual','operational')),revision text NOT NULL,source_ref text NOT NULL,source_type text NOT NULL,observed_at timestamptz,freshness text NOT NULL,support text NOT NULL,fields jsonb NOT NULL,PRIMARY KEY(id,project_id));
CREATE TABLE cmdb_unique_attribute(asset_type text NOT NULL,field_name text NOT NULL,value_key text NOT NULL,asset_id text NOT NULL REFERENCES cmdb_entity(item_uid),PRIMARY KEY(asset_type,field_name,value_key));
UPDATE outbox_event SET published_at=NULL WHERE event_type='bom.committed';
